fn meshgrid(x: Vec<f32>, y: Vec<f32>) -> (Vec<Vec<f32>>, Vec<Vec<f32>>) {
    let rows = y.len();
    let cols = x.len();
    
    // Create first matrix (xx): each row is a copy of x
    let mut xx = Vec::with_capacity(rows);
    for _ in 0..rows {
        xx.push(x.clone());
    }
    
    // Create second matrix (yy): each row has cols elements all equal to y[i]
    let mut yy = Vec::with_capacity(rows);
    for i in 0..rows {
        let row = vec![y[i]; cols];
        yy.push(row);
    }
    
    (xx, yy)
}